314: function isRecord(value: unknown): value is Record<string, unknown> {
315:   return typeof value === 'object' && value !== null && !Array.isArray(value);
316: }
317: 
318: function nonEmptyString(value: unknown, field: string): string {
319:   if (typeof value !== 'string' || value.trim() === '') {
320:     throw new TypeError(`${field} must be a non-empty string.`);
321:   }
322:   return value.trim();
323: }
324: 
325: function nonNegativeInteger(value: unknown, field: string): number {
326:   if (!Number.isInteger(value) || Number(value) < 0) {
327:     throw new TypeError(`${field} must be a non-negative integer.`);
328:   }
329:   return Number(value);
330: }
331: 
332: function positiveInteger(value: unknown, field: string): number {
333:   if (!Number.isInteger(value) || Number(value) < 1) {
334:     throw new TypeError(`${field} must be a positive integer.`);
335:   }
336:   return Number(value);
337: }
338: 
339: function finiteRatio(value: unknown, field: string): number {
340:   if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value > 1) {
341:     throw new TypeError(`${field} must be a finite number from 0 through 1.`);
342:   }
343:   return value;
344: }
345: 
346: function normalizeTrigger(value: string): string {
347:   return value.normalize('NFKC').toLowerCase().replace(/\s+/gu, ' ').trim();
348: }
349: 
350: function isoTimestamp(now: () => Date | string): string {
351:   const value = now();
352:   if (value instanceof Date) {
353:     return value.toISOString();
354:   }
355:   if (typeof value === 'string' && value.trim() !== '') {
356:     return value;
357:   }
358:   throw new TypeError('now must return a Date or non-empty ISO timestamp string.');
359: }
360: 
361: function canonicalize(value: unknown): unknown {
362:   if (Array.isArray(value)) {
363:     return value.map(canonicalize);
364:   }
365:   if (!isRecord(value)) {
366:     return value;
367:   }
368:   const result: Record<string, unknown> = {};
369:   for (const key of Object.keys(value).sort()) {
370:     result[key] = canonicalize(value[key]);
371:   }
372:   return result;
373: }
374: 
375: function stableJson(value: unknown): string {
376:   return JSON.stringify(canonicalize(value));
377: }
378: 
379: function isLifecycleTransition(value: unknown): value is PivotLifecycleTransition {
380:   if (!isRecord(value)
381:     || typeof value.from !== 'string'
382:     || typeof value.to !== 'string'
383:     || !PIVOT_LIFECYCLE_STATES.has(value.from)
384:     || !PIVOT_LIFECYCLE_STATES.has(value.to)) {
385:     return false;
386:   }
387:   return value.next === undefined
388:     || (typeof value.next === 'string' && PIVOT_LIFECYCLE_STATES.has(value.next));
389: }
390: 
391: function parsePivotEventName(value: unknown): PivotEventName | null {
392:   switch (value) {
393:     case 'pivot_started':
394:     case 'pivot_candidate_rejected':
395:     case 'pivot_seat_returned':
396:     case 'pivot_deliberation_completed':
397:     case 'pivot_selected':
398:     case 'pivot_completed':
399:     case 'pivot_failed':
400:       return value;
401:     default:
402:       return null;
403:   }
404: }
405: 
406: function parsePersistedPivotEvent(value: unknown, pivotId: string, index: number): PivotEvent {
407:   if (!isRecord(value)
408:     || value.schemaVersion !== 1
409:     || typeof value.eventId !== 'string'
410:     || value.eventId.trim() === ''
411:     || value.pivotId !== pivotId
412:     || typeof value.occurredAtIso !== 'string'
413:     || value.occurredAtIso.trim() === ''
414:     || !isLifecycleTransition(value.lifecycle)) {
415:     throw new Error(`Pivot state line ${index + 1} does not match the pivot event contract.`);
416:   }
417:   const event = parsePivotEventName(value.event);
418:   if (event === null || (event === 'pivot_failed'
419:     && (typeof value.reason !== 'string' || !PIVOT_FAILURE_REASONS.has(value.reason)))) {
420:     throw new Error(`Pivot state line ${index + 1} does not match the pivot event contract.`);
421:   }
422:   const parsed: PivotEvent = {
423:     ...value,
424:     schemaVersion: 1,
425:     eventId: value.eventId.trim(),
426:     event,
427:     pivotId,
428:     occurredAtIso: value.occurredAtIso.trim(),
429:     lifecycle: value.lifecycle,
430:   };
431:   return parsed;
432: }
