434: function resolveProspectiveRealPath(path: string): string {
435:   let current = resolve(path);
436:   const missingSegments: string[] = [];
437:   while (!existsSync(current)) {
438:     const parent = dirname(current);
439:     if (parent === current) {
440:       throw new TypeError(`Unable to resolve artifact path "${path}".`);
441:     }
442:     missingSegments.unshift(current.slice(parent.length + (parent.endsWith(sep) ? 0 : 1)));
443:     current = parent;
444:   }
445:   return join(realpathSync.native(current), ...missingSegments);
446: }
