457:       'antiConvergence.divergent.maxPivots',
458:     ),
459:     maxCouncilSeatOutputs: positiveInteger(
460:       divergent.maxCouncilSeatOutputs ?? DEFAULT_DIVERGENT_CONFIG.maxCouncilSeatOutputs,
461:       'antiConvergence.divergent.maxCouncilSeatOutputs',
462:     ),
463:     minRemainingIterations: nonNegativeInteger(
464:       divergent.minRemainingIterations ?? DEFAULT_DIVERGENT_CONFIG.minRemainingIterations,
465:       'antiConvergence.divergent.minRemainingIterations',
466:     ),
467:     candidateSimilarityThreshold: finiteRatio(
468:       divergent.candidateSimilarityThreshold
469:         ?? DEFAULT_DIVERGENT_CONFIG.candidateSimilarityThreshold,
470:       'antiConvergence.divergent.candidateSimilarityThreshold',
471:     ),
472:   };
