475: function normalizeUsage(usage: PivotUsage): PivotUsage {
476:   return {
477:     completedPivots: nonNegativeInteger(usage.completedPivots, 'usage.completedPivots'),
478:     councilSeatOutputs: nonNegativeInteger(
479:       usage.councilSeatOutputs,
480:       'usage.councilSeatOutputs',
481:     ),
482:     remainingIterations: nonNegativeInteger(
483:       usage.remainingIterations,
484:       'usage.remainingIterations',
485:     ),
486:     insidePivot: usage.insidePivot === true,
487:   };
