490: function normalizeSeats(seats: readonly PivotSeatMandate[]): readonly PivotSeatMandate[] {
491:   if (!Array.isArray(seats) || seats.length !== 3) {
492:     throw new TypeError('Exactly three Council seat mandates are required.');
493:   }
494:   const normalized = seats.map((seat, index) => {
495:     if (!isRecord(seat)) {
496:       throw new TypeError(`Seat at index ${index} must be an object.`);
497:     }
498:     const id = nonEmptyString(seat.id, `seats[${index}].id`);
499:     const mandate = nonEmptyString(seat.mandate, `seats[${index}].mandate`);
500:     if (id !== REQUIRED_SEAT_IDS[index]) {
501:       throw new TypeError(`Seat at index ${index} must use id "${REQUIRED_SEAT_IDS[index]}".`);
502:     }
503:     return { id, mandate };
504:   });
505:   const mandateKeys = new Set(normalized.map((seat) => normalizeTrigger(seat.mandate)));
506:   if (mandateKeys.size !== 3) {
507:     throw new TypeError('Council seat mandates must be distinct.');
508:   }
509:   return normalized;
510: }
