512: function validateIdentity(identity: PivotIdentityInput): PivotIdentityInput {
513:   const generation = typeof identity.generation === 'number'
514:     ? String(nonNegativeInteger(identity.generation, 'identity.generation'))
515:     : nonEmptyString(identity.generation, 'identity.generation');
516:   return {
517:     sessionId: nonEmptyString(identity.sessionId, 'identity.sessionId'),
518:     generation,
519:     loopType: nonEmptyString(identity.loopType, 'identity.loopType'),
520:     sourceIteration: nonNegativeInteger(identity.sourceIteration, 'identity.sourceIteration'),
521:     normalizedTrigger: normalizeTrigger(
522:       nonEmptyString(identity.normalizedTrigger, 'identity.normalizedTrigger'),
523:     ),
524:     ordinal: positiveInteger(identity.ordinal, 'identity.ordinal'),
525:   };
526: }
