563: function appendEvent(
564:   store: EventStore,
565:   statePath: string,
566:   pivotId: string,
567:   now: () => Date | string,
568:   observer: PivotEventObserver | undefined,
569:   event: Pick<PivotEvent, 'eventId' | 'event' | 'lifecycle'> & Record<string, unknown>,
570: ): PivotEvent {
571:   const candidate: PivotEvent = {
572:     schemaVersion: 1,
573:     ...event,
574:     pivotId,
575:     occurredAtIso: isoTimestamp(now),
576:   };
577:   const existing = store.byId.get(candidate.eventId);
578:   if (existing) {
579:     if (stableJson(eventSemanticPayload(existing)) !== stableJson(eventSemanticPayload(candidate))) {
580:       throw new Error(`Conflicting replay for pivot event "${candidate.eventId}".`);
581:     }
582:     return existing;
583:   }
584: 
585:   appendJsonlIfChangedAtomic(statePath, candidate, {
586:     cache: new Map<string, string>(),
587:     diffField: 'event_hash',
588:     diffData: eventSemanticPayload(candidate),
589:   });
590:   store.events.push(candidate);
591:   store.byId.set(candidate.eventId, candidate);
592:   observer?.(candidate);
593:   return candidate;
594: }
