719: function failureReasonForQuorum(quorum: PivotQuorumResult): PivotFailureReason {
720:   if (quorum.allFailed) {
721:     return 'council_all_seats_rejected';
722:   }
723:   if (quorum.fulfilled < 3) {
724:     return 'council_return_quorum_failed';
725:   }
726:   return 'council_parse_quorum_failed';
727: }
