729: function preflightFailure(
730:   config: NormalizedDivergentConfig,
731:   usage: PivotUsage,
732:   openingAttempt: boolean,
733: ): PivotFailureReason | null {
734:   if (usage.completedPivots >= config.maxPivots) {
735:     return 'max_pivots_exceeded';
736:   }
737:   // The cap bounds one council attempt. An attempt holds no seat outputs when it opens,
738:   // and a resumed attempt already passed this check when it opened.
739:   if (openingAttempt && 3 > config.maxCouncilSeatOutputs) {
740:     return 'max_council_seat_outputs_exceeded';
741:   }
742:   return null;
743: }
