745: function completedResultFromEvent(
746:   event: PivotEvent,
747:   paths: PivotCouncilPaths,
748:   resumed: boolean,
749: ): PivotCompletedResult {
750:   const validation = validatePivotCandidate(event.selectedCandidate);
751:   if (!validation.valid
752:     || event.currentFocus !== validation.candidate.focus
753:     || !isRecord(event.agreement)) {
754:     throw new Error('Durable pivot_completed event is missing restoration data.');
755:   }
756:   return {
757:     status: 'completed',
758:     pivotId: event.pivotId,
759:     paths,
760:     resumed,
761:     selectedCandidate: validation.candidate,
762:     restoredFocus: event.currentFocus,
763:     agreement: event.agreement as unknown as PivotAgreementResult,
764:     completedEvent: event,
765:   };
