768: function failedResultFromEvent(
769:   event: PivotEvent,
770:   paths: PivotCouncilPaths,
771:   resumed: boolean,
772: ): PivotFailedResult {
773:   return {
774:     status: 'failed',
775:     pivotId: event.pivotId,
776:     paths,
777:     resumed,
778:     failureReason: event.reason as PivotFailureReason,
779:     durable: true,
780:     ...(isRecord(event.quorum) ? { quorum: event.quorum as unknown as PivotQuorumResult } : {}),
781:     ...(isRecord(event.agreement)
782:       ? { agreement: event.agreement as unknown as PivotAgreementResult }
783:       : {}),
784:     failedEvent: event,
785:   };
786: }
