836: /** Parse and validate an injected seat output without accepting partial reports. */
837: export function parsePivotSeatReport(
838:   output: unknown,
839:   expectedSeatId: string,
840:   candidateIds: ReadonlySet<string>,
841: ): PivotSeatReportParseResult {
842:   let parsed = output;
843:   if (typeof parsed === 'string') {
844:     try {
845:       parsed = JSON.parse(parsed);
846:     } catch {
847:       return { valid: false, reason: 'Seat output must be a JSON object or JSON object string.' };
848:     }
849:   }
850:   if (!isRecord(parsed)) {
851:     return { valid: false, reason: 'Seat output must be an object.' };
852:   }
853:   if (parsed.seatId !== expectedSeatId) {
854:     return { valid: false, reason: `Seat report must identify itself as "${expectedSeatId}".` };
855:   }
856:   const selectedCandidateId = parsed.selectedCandidateId;
857:   if (selectedCandidateId !== null
858:     && (typeof selectedCandidateId !== 'string' || !candidateIds.has(selectedCandidateId))) {
859:     return { valid: false, reason: 'selectedCandidateId must be null or identify a valid candidate.' };
860:   }
861:   if (typeof parsed.materialEndorsement !== 'boolean') {
862:     return { valid: false, reason: 'materialEndorsement must be a boolean.' };
863:   }
864:   if (parsed.materialEndorsement && selectedCandidateId === null) {
865:     return { valid: false, reason: 'A material endorsement must identify a selected candidate.' };
866:   }
867:   if (typeof parsed.rationale !== 'string' || parsed.rationale.trim() === '') {
868:     return { valid: false, reason: 'Seat rationale must be a non-empty string.' };
869:   }
870:   if (!Array.isArray(parsed.blockers)) {
871:     return { valid: false, reason: 'Seat blockers must be an array.' };
872:   }
873:   const blockers = parsed.blockers.map((blocker) => parseBlocker(blocker, candidateIds));
874:   if (blockers.some((blocker) => blocker === null)) {
875:     return { valid: false, reason: 'Every seat blocker must match the blocker contract.' };
876:   }
877:   return {
878:     valid: true,
879:     report: {
880:       seatId: expectedSeatId,
881:       selectedCandidateId: selectedCandidateId as string | null,
882:       materialEndorsement: parsed.materialEndorsement,
883:       rationale: parsed.rationale.trim(),
884:       blockers: blockers as PivotSeatBlocker[],
885:     },
886:   };
887: }
