889: /** Evaluate two-of-three material endorsement and the global high-blocker veto. */
890: export function evaluatePivotAgreement(
891:   reports: readonly PivotSeatReport[],
892:   candidateOrder: readonly string[],
893: ): PivotAgreementResult {
894:   const highSeverityBlockers = reports.flatMap((report) =>
895:     report.blockers.filter((blocker) => blocker.severity === 'high'));
896:   const tallies = candidateOrder.map((candidateId) => {
897:     const endorsingSeatIds = reports
898:       .filter((report) => report.materialEndorsement && report.selectedCandidateId === candidateId)
899:       .map((report) => report.seatId);
900:     return { candidateId, endorsementCount: endorsingSeatIds.length, endorsingSeatIds };
901:   });
902:   const selected = tallies.find((tally) => tally.endorsementCount >= 2) ?? null;
903:   const converged = reports.length === 3 && selected !== null && highSeverityBlockers.length === 0;
904:   return {
905:     converged,
906:     selectedCandidateId: selected?.candidateId ?? null,
907:     endorsementCount: selected?.endorsementCount ?? 0,
908:     endorsingSeatIds: selected?.endorsingSeatIds ?? [],
909:     tallies,
910:     highSeverityBlockers,
911:     reason: highSeverityBlockers.length > 0
912:       ? 'high_severity_blocker'
913:       : selected === null
914:         ? 'insufficient_endorsement'
915:         : 'agreed',
916:   };
917: }
