1178: /** Validate, dedupe, and persist through "which seats remain to dispatch" — no seat dispatch here. */
1179: export async function preparePivotTransaction(
1180:   options: PreparePivotTransactionOptions,
1181: ): Promise<PivotPrepareResult> {
1182:   if (!isRecord(options)) {
1183:     throw new TypeError('preparePivotTransaction options must be an object.');
1184:   }
1185: 
1186:   const identity = validateIdentity(options.identity);
1187:   const pivotId = derivePivotId(identity);
1188:   const paths = buildPivotCouncilPaths(options.artifactRoot, pivotId);
1189:   const requestedUsage = normalizeUsage(options.usage);
1190:   const config = normalizeConfig(options.config);
1191:   const seats = normalizeSeats(options.seats);
1192:   const previousFocus = nonEmptyString(options.previousFocus, 'previousFocus');
1193:   const saturatedDirections = (options.saturatedDirections ?? []).map((direction, index) =>
1194:     nonEmptyString(direction, `saturatedDirections[${index}]`));
1195:   const now = options.now ?? (() => new Date());
1196: 
1197:   if (requestedUsage.insidePivot || pivotExecutionContext.getStore() === true) {
1198:     return {
1199:       status: 'failed',
1200:       pivotId,
1201:       paths,
1202:       resumed: false,
1203:       failureReason: 'recursion_guard',
1204:       durable: false,
1205:     };
1206:   }
1207: 
1208:   const store = readEventStore(paths.statePath, pivotId);
1209:   const completedEvent = eventByName(store, 'pivot_completed');
1210:   const failedEvent = eventByName(store, 'pivot_failed');
1211:   if (completedEvent && failedEvent) {
1212:     throw new Error('Pivot state contains both completed and failed outcomes.');
1213:   }
1214:   if (completedEvent) {
1215:     writeMarkdownIfConsistent(paths.reportPath, renderReportArtifact(completedEvent));
1216:     return completedResultFromEvent(completedEvent, paths, true);
1217:   }
1218:   if (failedEvent) {
1219:     writeMarkdownIfConsistent(paths.reportPath, renderReportArtifact(failedEvent));
1220:     return failedResultFromEvent(failedEvent, paths, true);
1221:   }
1222: 
1223:   // A resume keeps the counts recorded when the pivot opened, so replaying its
1224:   // config and pivot_started event cannot conflict with the counts reported now.
1225:   const resumed = eventByName(store, 'pivot_started') !== undefined;
1226:   const usage = resumed
1227:     ? readPersistedConfig(paths.configPath, pivotId).usageAtStart
1228:     : requestedUsage;
1229: 
1230:   const candidateSet = deduplicatePivotCandidates(
1231:     options.candidates,
1232:     options.priorCandidates ?? [],
1233:     { candidateSimilarityThreshold: config.candidateSimilarityThreshold },
1234:   );
1235:   const configRecord: PersistedPivotConfig = {
1236:     schemaVersion: 1,
1237:     pivotId,
1238:     identity,
1239:     invariants: { rounds: 1, seats: 3, depth: 1, recursionAllowed: false },
1240:     limits: config,
1241:     usageAtStart: usage,
1242:     seats,
1243:     acceptedCandidates: candidateSet.accepted,
1244:     rejectedCandidates: candidateSet.rejected,
1245:     previousFocus,
1246:     saturatedDirections,
1247:   };
1248:   mkdirSync(paths.councilRoot, { recursive: true });
1249:   persistConfig(paths.configPath, configRecord as unknown as Record<string, unknown>);
1250: 
1251:   appendEvent(
1252:     store,
1253:     paths.statePath,
1254:     pivotId,
1255:     now,
1256:     options.afterEventPersisted,
1257:     {
1258:       eventId: `${pivotId}:pivot_started`,
1259:       event: 'pivot_started',
1260:       lifecycle: { from: 'LEGAL_STOP', to: 'PIVOT_PENDING', next: 'COUNCIL_RUNNING' },
1261:       ordinal: identity.ordinal,
1262:       source: identity,
1263:       previousFocus,
1264:       saturatedDirections,
1265:       priorPivotCount: usage.completedPivots,
1266:       priorCouncilSeatOutputs: usage.councilSeatOutputs,
1267:       remainingIterations: usage.remainingIterations,
1268:       acceptedCandidateIds: candidateSet.accepted.map((candidate) => candidate.id),
1269:     },
1270:   );
1271: 
1272:   candidateSet.rejected.forEach((rejection, index) => {
1273:     appendEvent(
1274:       store,
1275:       paths.statePath,
1276:       pivotId,
1277:       now,
1278:       options.afterEventPersisted,
1279:       {
1280:         eventId: candidateRejectionEventId(pivotId, rejection, index),
1281:         event: 'pivot_candidate_rejected',
1282:         lifecycle: { from: 'PIVOT_PENDING', to: 'PIVOT_PENDING' },
1283:         candidate: rejection.candidate ?? null,
1284:         normalizedFingerprint: rejection.normalizedFingerprint ?? null,
1285:         reasons: rejection.rejections,
1286:       },
1287:     );
1288:   });
1289: 
1290:   const durableSeatEvents = new Map<string, PivotEvent>();
1291:   for (const seat of seats) {
1292:     const event = store.byId.get(seatEventId(pivotId, seat.id));
1293:     if (event) {
1294:       durableSeatEvents.set(seat.id, event);
1295:     }
1296:   }
1297:   const preflightReason = preflightFailure(config, usage, durableSeatEvents.size === 0);
1298:   const earlyFailureReason = preflightReason
1299:     ?? (candidateSet.accepted.length === 0 ? 'no_valid_candidates' : null);
1300:   if (earlyFailureReason) {
1301:     const failed = appendEvent(
1302:       store,
1303:       paths.statePath,
1304:       pivotId,
1305:       now,
1306:       options.afterEventPersisted,
1307:       {
1308:         eventId: `${pivotId}:pivot_failed`,
1309:         event: 'pivot_failed',
1310:         lifecycle: { from: 'PIVOT_PENDING', to: 'PIVOT_PENDING' },
1311:         reason: earlyFailureReason,
1312:         recoverableByOverride: false,
1313:       },
1314:     );
1315:     writeMarkdownIfConsistent(paths.reportPath, renderReportArtifact(failed));
1316:     return failedResultFromEvent(failed, paths, resumed);
1317:   }
1318: 
1319:   if (durableSeatEvents.size > 0) {
1320:     mkdirSync(paths.seatsRoot, { recursive: true });
1321:     seats.forEach((seat, index) => {
1322:       const event = durableSeatEvents.get(seat.id);
1323:       if (event) {
1324:         writeMarkdownIfConsistent(paths.seatPaths[index], renderSeatArtifact(event));
1325:       }
1326:     });
1327:   }
1328: 
1329:   const missingSeats = seats.filter((seat) => !durableSeatEvents.has(seat.id));
1330:   return {
1331:     status: 'pending',
1332:     pivotId,
1333:     paths,
1334:     resumed,
1335:     missingSeats,
1336:     dispatchContext: {
1337:       pivotId,
1338:       round: 1,
1339:       depth: 1,
