806: /** Build and validate the isolated artifact paths for one pivot Council transaction. */
807: export function buildPivotCouncilPaths(artifactRoot: string, pivotId: string): PivotCouncilPaths {
808:   const rootInput = nonEmptyString(artifactRoot, 'artifactRoot');
809:   if (!/^pivot-[1-9][0-9]*-[a-f0-9]{12}$/u.test(pivotId)) {
810:     throw new TypeError('pivotId must match pivot-<ordinal>-<12 lowercase hex characters>.');
811:   }
812:   const canonicalRoot = resolveProspectiveRealPath(rootInput);
813:   if (pathContainsAiCouncil(canonicalRoot)) {
814:     throw new TypeError('artifactRoot must not be inside an ai-council artifact tree.');
815:   }
816:   const pivotRoot = join(canonicalRoot, 'divergent', 'pivots', pivotId);
817:   const councilRoot = join(pivotRoot, 'council');
818:   const seatsRoot = join(councilRoot, 'seats');
819:   return {
820:     artifactRoot: canonicalRoot,
821:     pivotRoot,
822:     councilRoot,
823:     configPath: join(councilRoot, 'config.json'),
824:     statePath: join(councilRoot, 'state.jsonl'),
825:     seatsRoot,
826:     seatPaths: [
827:       join(seatsRoot, 'seat-001.md'),
828:       join(seatsRoot, 'seat-002.md'),
829:       join(seatsRoot, 'seat-003.md'),
830:     ],
831:     deliberationPath: join(councilRoot, 'deliberation.md'),
832:     reportPath: join(councilRoot, 'report.md'),
833:   };
834: }
