1008: function parsePersistedIdentity(value: unknown): PivotIdentityInput {
1009:   if (!isRecord(value)) throw new Error('Persisted pivot identity must be an object.');
1010:   const generation = typeof value.generation === 'number'
1011:     ? String(nonNegativeInteger(value.generation, 'identity.generation'))
1012:     : nonEmptyString(value.generation, 'identity.generation');
1013:   return {
1014:     sessionId: nonEmptyString(value.sessionId, 'identity.sessionId'),
1015:     generation,
1016:     loopType: nonEmptyString(value.loopType, 'identity.loopType'),
1017:     sourceIteration: nonNegativeInteger(value.sourceIteration, 'identity.sourceIteration'),
1018:     normalizedTrigger: normalizeTrigger(nonEmptyString(value.normalizedTrigger, 'identity.normalizedTrigger')),
1019:     ordinal: positiveInteger(value.ordinal, 'identity.ordinal'),
1020:   };
1021: }
1022: 
1023: function parsePersistedLimits(value: unknown): NormalizedDivergentConfig {
1024:   if (!isRecord(value)) throw new Error('Persisted pivot limits must be an object.');
1025:   const required = ['maxPivots', 'maxCouncilSeatOutputs', 'minRemainingIterations', 'candidateSimilarityThreshold'];
1026:   if (required.some((key) => !Object.prototype.hasOwnProperty.call(value, key))) {
1027:     throw new Error('Persisted pivot limits are incomplete.');
1028:   }
1029:   return {
1030:     maxPivots: positiveInteger(value.maxPivots, 'limits.maxPivots'),
1031:     maxCouncilSeatOutputs: positiveInteger(value.maxCouncilSeatOutputs, 'limits.maxCouncilSeatOutputs'),
1032:     minRemainingIterations: nonNegativeInteger(value.minRemainingIterations, 'limits.minRemainingIterations'),
1033:     candidateSimilarityThreshold: finiteRatio(value.candidateSimilarityThreshold, 'limits.candidateSimilarityThreshold'),
1034:   };
1035: }
1036: 
1037: function parsePersistedUsage(value: unknown): PivotUsage {
1038:   if (!isRecord(value)) throw new Error('Persisted pivot usage must be an object.');
1039:   return {
1040:     completedPivots: nonNegativeInteger(value.completedPivots, 'usageAtStart.completedPivots'),
1041:     councilSeatOutputs: nonNegativeInteger(value.councilSeatOutputs, 'usageAtStart.councilSeatOutputs'),
1042:     remainingIterations: nonNegativeInteger(value.remainingIterations, 'usageAtStart.remainingIterations'),
1043:     insidePivot: value.insidePivot === true,
1044:   };
1045: }
1046: 
1047: function parsePersistedSeats(value: unknown): readonly PivotSeatMandate[] {
1048:   if (!Array.isArray(value)) throw new Error('Persisted pivot seats must be an array.');
1049:   return normalizeSeats(value.map((seat, index) => {
1050:     if (!isRecord(seat)) throw new Error(`Persisted seat at index ${index} must be an object.`);
1051:     return {
1052:       id: nonEmptyString(seat.id, `seats[${index}].id`),
1053:       mandate: nonEmptyString(seat.mandate, `seats[${index}].mandate`),
1054:     };
1055:   }));
1056: }
1057: 
1058: function parsePersistedCandidates(value: unknown, field: string): readonly PivotCandidate[] {
1059:   if (!Array.isArray(value)) throw new Error(`Persisted ${field} must be an array.`);
1060:   return value.map((candidate, index) => {
1061:     const validation = validatePivotCandidate(candidate);
1062:     if (!validation.valid) {
1063:       throw new Error(`Persisted ${field}[${index}] is not a valid pivot candidate.`);
1064:     }
1065:     return validation.candidate;
1066:   });
1067: }
1068: 
1069: function parsePersistedRejectedCandidates(value: unknown): readonly RejectedPivotCandidateDeduplication[] {
1070:   if (!Array.isArray(value)) throw new Error('Persisted rejectedCandidates must be an array.');
1071:   return value.map((entry, index) => {
1072:     if (!isRecord(entry)
1073:       || entry.accepted !== false
1074:       || typeof entry.maxSimilarity !== 'number'
1075:       || !Number.isFinite(entry.maxSimilarity)
1076:       || entry.maxSimilarity < 0
1077:       || entry.maxSimilarity > 1
1078:       || !Array.isArray(entry.rejections)) {
1079:       throw new Error(`Persisted rejectedCandidates[${index}] is invalid.`);
1080:     }
1081:     const rejections = entry.rejections.map((rejection, rejectionIndex) => {
1082:       if (!isRecord(rejection)
1083:         || typeof rejection.code !== 'string'
1084:         || typeof rejection.message !== 'string'
1085:         || rejection.message.trim() === '') {
1086:         throw new Error(`Persisted rejectedCandidates[${index}].rejections[${rejectionIndex}] is invalid.`);
1087:       }
1088:       const code = rejection.code;
1089:       if (code !== 'invalid_candidate'
1090:         && code !== 'invalid_prior_candidate'
1091:         && code !== 'duplicate_id'
1092:         && code !== 'exact_duplicate'
1093:         && code !== 'materially_similar') {
1094:         throw new Error(`Persisted rejectedCandidates[${index}] has an unknown rejection code.`);
1095:       }
1096:       if (rejection.similarity !== undefined
1097:         && (typeof rejection.similarity !== 'number'
1098:           || !Number.isFinite(rejection.similarity)
1099:           || rejection.similarity < 0
1100:           || rejection.similarity > 1)) {
1101:         throw new Error(`Persisted rejectedCandidates[${index}] has an invalid similarity.`);
1102:       }
1103:       const parsed: RejectedPivotCandidateDeduplication['rejections'][number] = {
1104:         code,
1105:         message: rejection.message.trim(),
1106:         ...(typeof rejection.field === 'string' ? { field: rejection.field } : {}),
1107:         ...(typeof rejection.priorCandidateId === 'string' ? { priorCandidateId: rejection.priorCandidateId } : {}),
1108:         ...(typeof rejection.similarity === 'number' && Number.isFinite(rejection.similarity)
1109:           ? { similarity: rejection.similarity }
1110:           : {}),
1111:       };
1112:       return parsed;
1113:     });
1114:     const candidate = entry.candidate === undefined ? undefined : parsePersistedCandidates([entry.candidate], 'candidate')[0];
1115:     const normalizedFingerprint = entry.normalizedFingerprint;
1116:     if (normalizedFingerprint !== undefined
1117:       && (typeof normalizedFingerprint !== 'string' || normalizedFingerprint.trim() === '')) {
1118:       throw new Error(`Persisted rejectedCandidates[${index}] has an invalid fingerprint.`);
1119:     }
1120:     return {
1121:       accepted: false,
1122:       maxSimilarity: entry.maxSimilarity,
